28	    at::ScalarType scalar_data_type = at_scalar.type();
29	    aclDataType acl_data_type = kATenScalarTypeToAclDataTypeTable[static_cast<int64_t>(scalar_data_type)];
30	    TORCH_CHECK(
31	        acl_data_type != ACL_DT_UNDEFINED, std::string(c10::toString(scalar_data_type)) + " has not been supported")
32	    aclScalar *acl_scalar = nullptr;
33	    switch (scalar_data_type) {
34	        case at::ScalarType::Double: {
35	            double value = at_scalar.toDouble();
36	            acl_scalar = aclCreateScalar(&value, acl_data_type);
