174	inline aclTensor *ConvertType(const TensorWrapper &tensor_r) {
175	    static const auto aclCreateTensor = GET_OP_API_FUNC(aclCreateTensor);
176	    if (aclCreateTensor == nullptr)
177	        return nullptr;
178	
179	    const at::Tensor &at_tensor = tensor_r.tensor_;
180	
181	    if (!at_tensor.defined())
182	        return nullptr;
183	
184	    TORCH_CHECK(torch_npu::utils::is_npu(at_tensor),
185	        "Expected all tensors to be on the same device. "
186	        "Expected NPU tensor, please check whether the input tensor device is correct.",
187	        OPS_ERROR(ErrCode::TYPE));
188	
189	    aclDataType acl_data_type = tensor_r.dtype;
190	    c10::SmallVector<int64_t, MAX_DIM_NUM> storageDims;
191	    c10::SmallVector<int64_t, MAX_DIM_NUM> wrapperStride = array_to_small_vector(at_tensor.strides());
192	    c10::SmallVector<int64_t, MAX_DIM_NUM> wrapperShape = array_to_small_vector(at_tensor.sizes());
193	
194	    const auto dimNum = at_tensor.sizes().size();
195	    aclFormat format = ACL_FORMAT_ND;
196	    if (!at_npu::native::FormatHelper::IsOpInputBaseFormat(at_tensor)) {
197	        format = torch_npu::NPUBridge::GetNpuStorageImpl(at_tensor)->npu_desc_.npu_format_;
198	        // if acl_data_type is ACL_STRING, storageDims is empty.
199	        if (acl_data_type != ACL_STRING) {
200	            TORCH_CHECK(
201	                at_tensor.itemsize() > 0, "the itemsize of tensor must be greater than 0.", OPS_ERROR(ErrCode::VALUE));
202	            storageDims = torch_npu::NPUBridge::GetNpuStorageImpl(at_tensor)->npu_desc_.storage_sizes_;
203	        }
204	    } else {
205	        switch (dimNum) {
206	            case NCL_DIM_NUM: format = ACL_FORMAT_NCL; break;
207	            case NCHW_DIM_NUM: format = ACL_FORMAT_NCHW; break;
208	            case NCDHW_DIM_NUM: format = ACL_FORMAT_NCDHW; break;
209	            default: format = ACL_FORMAT_ND;
210	        }
211	        // if acl_data_type is ACL_STRING, storageDims is empty.
212	        if (acl_data_type != ACL_STRING) {
213	            TORCH_CHECK(
214	                at_tensor.itemsize() > 0, "the itemsize of tensor must be greater than 0.", OPS_ERROR(ErrCode::VALUE));
215	            storageDims.push_back(at_tensor.storage().nbytes() / at_tensor.itemsize());
216	        }
217	    }
218	
219	    auto acl_tensor = aclCreateTensor(wrapperShape.data(), at_tensor.sizes().size(), acl_data_type,
220	        wrapperStride.data(), at_tensor.storage_offset(), format, storageDims.data(), storageDims.size(),
221	        const_cast<void *>(at_tensor.storage().data()));
222	    return acl_tensor;
223	}
