389	        static const auto getWorkspaceSizeFuncAddr = GetOpApiFuncAddr(#aclnn_api "GetWorkspaceSize");                \
390	        static const auto opApiFuncAddr = GetOpApiFuncAddr(#aclnn_api);                                              \
391	        static const auto initMemAddr = GetOpApiFuncAddr("InitHugeMemThreadLocal");                                  \
392	        static const auto unInitMemAddr = GetOpApiFuncAddr("UnInitHugeMemThreadLocal");                              \
393	        static const auto releaseMemAddr = GetOpApiFuncAddr("ReleaseHugeMem");                                       \
394	        static const auto initPTACacheThreadLocalAddr = GetOpApiFuncAddr("InitPTACacheThreadLocal");                 \
395	        static const auto setPTAHashKeyAddr = GetOpApiFuncAddr("SetPTAHashKey");                                     \
396	        TORCH_CHECK(getWorkspaceSizeFuncAddr != nullptr && opApiFuncAddr != nullptr, #aclnn_api, " or ",             \
397	            #aclnn_api "GetWorkspaceSize", " not in ", GetOpApiLibName(), ", or ", GetOpApiLibName(), "not found."); \
398	        auto acl_stream = c10_npu::getCurrentNPUStream().stream(false);                                              \
399	        uint64_t workspace_size = 0;                                                                                 \
400	        uint64_t *workspace_size_addr = &workspace_size;                                                             \
401	        aclOpExecutor *executor = nullptr;                                                                           \
402	        aclOpExecutor **executor_addr = &executor;                                                                   \
403	        InitHugeMemThreadLocal initMemFunc = reinterpret_cast<InitHugeMemThreadLocal>(initMemAddr);                  \
404	        UnInitHugeMemThreadLocal unInitMemFunc = reinterpret_cast<UnInitHugeMemThreadLocal>(unInitMemAddr);          \
405	        InitPTACacheThreadLocal initPTACacheThreadLocalFunc =                                                        \
406	            reinterpret_cast<InitPTACacheThreadLocal>(initPTACacheThreadLocalAddr);                                  \
407	        SetPTAHashKey setPTAHashKeyFunc = reinterpret_cast<SetPTAHashKey>(setPTAHashKeyAddr);                        \
408	        if (initPTACacheThreadLocalFunc && setPTAHashKeyFunc) {                                                      \
409	            initPTACacheThreadLocalFunc();                                                                           \
410	            setPTAHashKeyFunc(0);                                                                                    \
411	        }                                                                                                            \
412	        if (initMemFunc) {                                                                                           \
413	            initMemFunc(nullptr, false);                                                                             \
414	        }                                                                                                            \
415	        auto converted_params = ConvertTypes(__VA_ARGS__, workspace_size_addr, executor_addr);                       \
416	        static auto getWorkspaceSizeFunc = ConvertToOpApiFunc(converted_params, getWorkspaceSizeFuncAddr);           \
417	        auto workspace_status = call(getWorkspaceSizeFunc, converted_params);                                        \
418	        TORCH_CHECK(workspace_status == 0, "call " #aclnn_api " failed");                                            \
419	        void *workspace_addr = nullptr;                                                                              \
420	        at::Tensor workspace_tensor;                                                                                 \
